def match(pattern: str, text: str) -> bool:
    """
    Implements basic regex matching using recursion and backtracking.
    Supports literal characters, '.', '*', and '+' in the pattern.
    """
    def dp(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern) and t_idx == len(text):
            return True
        if p_idx < len(pattern) and pattern[p_idx] == '*':
            return dp(p_idx + 2, t_idx) or (t_idx < len(text) and dp(p_idx, t_idx + 1))
        if p_idx < len(pattern) and pattern[p_idx] == '+':
            if t_idx < len(text) and (pattern[p_idx - 1] == text[t_idx] or pattern[p_idx - 1] == '.'):
                return dp(p_idx, t_idx + 1) or dp(p_idx + 1, t_idx)  # one or more
            return False
        if p_idx < len(pattern) and t_idx < len(text) and (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.'):
            return dp(p_idx + 1, t_idx + 1)
        return False

    return dp(0, 0)

