    """
    Implements basic regex matching using dynamic programming.
    Supports literal characters, '.', '*', and '+' in the pattern.
    """
    m, n = len(text), len(pattern)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 2][0]

