            elif pattern[i - 1] == '+':
                dp[i][j] = (dp[i - 1][j - 1] and (text[j - 1] == pattern[i - 2] or pattern[i - 2] == '.')) or (dp[i][j - 1] and (text[j - 1] == pattern[i - 2] or pattern[i - 2] == '.'))

    return dp[n][m]

